// Standalone fallback: resolve client_config from the Notion registry by client_id.
// The n8n Notion node flattens properties as 'property_<snake_cased_name>'; prop() tolerates both.
const trigger = $('Execute Workflow Trigger').first().json;
const wantId = trigger.client_id;
const rows = $input.all();
function prop(props, name){ const keys=[name,'property_'+name,'property_'+String(name).toLowerCase().replace(/ /g,'_')]; let p; for(const k of keys){ const v=props&&props[k]; if(v!==undefined&&v!==null){ p=v; break; } } if(p===undefined||p===null) return null; if(typeof p==='string') return p; return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'client_id')===wantId){ match=props; break; } }
if(!match) throw new Error(`No client registry row found for client_id='${wantId}'`);
const client_config = {
  client_id: wantId,
  client_name: prop(match,'Client Name'),
  reference_docs_folder_id: prop(match,'reference_docs_folder_id')
};
return [{ json: { client_id: wantId, client_config, data: trigger.data, status: 'ok', errors: [] } }];

// Concatenate the extracted text of the client's reference docs into one grounding block.
// The old caps (1500 chars/doc, 6000 total) allowed about a thousand words of evidence to
// ground a document that should run to eight thousand. Raised, and split per agent in
// 'Plan Chapters'. grounded_on records provenance for traceability.
const items = $input.all();
const parts = [];
const names = [];
for (const it of items) {
  const t = it.json.text || it.json.data || '';
  if (t) parts.push(String(t).slice(0, 6000));
  if (it.json.name) names.push(it.json.name);
}
const grounding = parts.join('\n\n---\n\n').slice(0, 24000);
return [{ json: { grounding, grounded_on: names } }];

